const body = $json.body ?? $json;
const job = String(body.job_description || '').trim();
const resume = String(body.resume || '').trim();
if (!job) throw new Error('job_description is required');
return [{json:{job_description:job,resume,requested_action:body.requested_action || 'analyze',timestamp:new Date().toISOString()}}];

const text=$json.job_description.toLowerCase();
const skills=['python','llm','rag','langchain','openai','sql','docker','aws','azure','n8n','api','machine learning','nlp','agents','typescript','react'];
const matched=skills.filter(s=>text.includes(s));
const score=Math.min(98,35+matched.length*5);
return [{json:{...$json,matched_skills:matched,fit_score:score,recommendation:score>=70?'Strong match':score>=50?'Potential match':'Low match'}}];

const matched=($json.matched_skills||[]).join(', ');
const letter='Dear Hiring Team,

I am excited to apply for this opportunity. My background in AI application engineering includes Python, LLM/RAG systems, agent workflows, REST APIs and production-oriented automation.

Relevant requirements identified in this role include: '+(matched||'AI application development')+'. I would welcome the opportunity to discuss how I can contribute to your team.

Best regards,
Huda Mohsin';
return [{json:{...$json,generated_cover_letter:letter,approval_required:true,status:'awaiting_human_approval'}}];
